export function chartWindow(total,offset=0,size=80){const back=Math.min(Math.max(0,Math.round(offset)),Math.max(0,total-size));const end=total-back;return {start:Math.max(0,end-size),end,offset:back,max:Math.max(0,total-size)};}
export function positionSeries(history,p){return history.filter(q=>q.time>=p.created).map(q=>({time:q.time,value:(p.side==='buy'?q.bid-p.entry:p.entry-q.ask)*p.units}));}
export function drawPosition(canvas,history,p){const points=positionSeries(history,p),r=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,r.width*dpr);canvas.height=r.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const w=r.width,h=r.height;let lo=Math.min(0,...points.map(q=>q.value)),hi=Math.max(0,...points.map(q=>q.value));if(hi===lo){hi+=1;lo-=1;}const y=v=>12+(hi-v)/(hi-lo)*Math.max(1,h-32);c.strokeStyle='#455266';c.setLineDash([3,4]);c.beginPath();c.moveTo(0,y(0));c.lineTo(w,y(0));c.stroke();c.setLineDash([]);if(points.length){c.strokeStyle=points.at(-1).value>=0?'#64e7b0':'#ff7989';c.lineWidth=1.7;c.beginPath();points.forEach((q,i)=>{const x=6+i*(w-12)/Math.max(1,points.length-1);i?c.lineTo(x,y(q.value)):c.moveTo(x,y(q.value));});c.stroke();}c.fillStyle='#94a6bc';c.font='10px sans-serif';c.fillText(points.length?`浮盈轨迹 · ${points.length} 个报价点`:'等待下一分钟报价',6,h-5);}

